import java.util.Iterator;
import java.util.Random;
import java.util.List;

/**
 * A class representing additional characteristics for predators.
 * Inlucdes an additional method for carnivores which allow them to step
 * on the grass without eating it.
 *
 * @version 2022.03.01
 */
public abstract class Predator extends Animal
{

    /**
     * Create a new predator at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     *
     */public Predator(Field field, Location location){
        super(field, location);
    }

    /**
     * If food is not found then the animal moves towards the nearest plant.
     * It does not eat the plant, instead stands on top of it.
     * @param probability The probability the animal finds prey.
     * @return Where plant was found, or null if it wasn't.
     */
    protected Location findFood(double probability)
    {
        if (super.findFood(probability) == null){
            Field field = getField();
            List<Location> adjacent = field.adjacentLocations(getLocation());
            Iterator<Location> it = adjacent.iterator();
            while(it.hasNext()) {
                Location where = it.next();
                Object actor = field.getObjectAt(where);
                if(actor != null && actor  instanceof Plants){
                    return where;
                }
            }
        }
        return null;
    }
}

import java.util.List;
import java.util.Random;
import java.util.Iterator;
import java.util.HashMap;

/**
 * A class representing shared characteristics of animals.
 *
 * @version 2022.03.01
 */
public abstract class Animal extends Actor
{
    private double foodLevel;
    private boolean isGirl;
    private boolean isHealthy;
    //the number of steps an animal takes when infected.
    private int infectedStepCounter;
    //how many steps animal needs to wait before it can breed again.
    private int timeLeftUntilBreedingAgain = 0;
    /**
     * Create a new animal at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Animal(Field field, Location location)
    {
        super(field,location);
        setRandomGender();
        isHealthy = true;
        infectedStepCounter = 0;
        timeLeftUntilBreedingAgain= getRandom().nextInt(getMaxTimeUntilBreedingAgain());
        if(!isGirl){
        timeLeftUntilBreedingAgain = 0;
        }
    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * @param newAnimals A list to receive newly born animals.
     * @param simulator The simulator.
     */
    public void act(List<Actor> newAnimals, Simulator simulator){
        Location newLocation = null;
        switch(simulator.getWeather()){
            case SUNNY:
                newLocation = findFood(getSunnyFindingFoodProbability());
                break;
            case RAINY:
                newLocation = findFood(getRainyFindingFoodProbability());
                break;
            case FOGGY:
                newLocation = findFood(getFoggyFindingFoodProbability());
                break;
            default:
                findFood(getRandom().nextDouble());
                break;
        }
        if(newLocation == null) { 
            // No food found - try to move to a free location.
            newLocation = getField().freeAdjacentLocation(getLocation());
        }
        if(newLocation != null) {
            setLocation(newLocation);
        }
        else {
            // Overcrowding.
            setDead();
        }
    }

    /**
     * An animal can breed if it has reached the breeding age.
     * @return true if an animal is able to breed
     */
    protected boolean canBreed()
    {
        return getAge() >= getBreedingAge();
    }

    /**
     * Get breeding age of an animal.
     * @return int. Breeding age of the animal;
     */
    abstract protected int getBreedingAge();

    /**
     * Check whether or not this animal is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newAnimals A list to return newly born animals.
     */
    protected void giveBirth(List<Actor> newAnimals)
    {
        // New animals are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        if (timeLeftUntilBreedingAgain != 0){
            timeLeftUntilBreedingAgain --;
        }
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Animal young = getAnimal();
            Animal baby = null;
            if(young instanceof Gazelle){
                baby = new Gazelle(false, field, loc);
            }else if(young instanceof Jaguar){
                baby = new Jaguar(false, field, loc);
            }else if(young instanceof Cheetah){
                baby = new Cheetah(false, field, loc);
            }else if(young instanceof Lion){
                baby = new Lion(false, field, loc);
            }else if(young instanceof Zebra){
                baby = new Zebra(false, field, loc);
            }
            if(!getHealth()){
                baby.setUnhealthy(); //setting the baby to be unhealthy if the parent is unhealthy.
            }
            newAnimals.add(baby);
        }
    }

    /**
     * Generate a number representing the number of births,
     * if it can breed.
     * Females can mate with a male even  regardless of the males breeding time .
     * @return The number of births (may be zero).
     */
    protected int breed()
    {
        int births = 0;
        if(canBreed()  && findMate() && getRandom().nextDouble() <= getBreedingProbability() && timeLeftUntilBreedingAgain == 0) {
            births = getRandom().nextInt(getMaxLitterSize()) + 1;
            timeLeftUntilBreedingAgain = getMaxTimeUntilBreedingAgain();
        }
        return births;
    }

    /**
     * If the animal can find a mate of the opposite gender that can breed, true is returned.
     * @return true if the animal can find a mate.
     */
    protected boolean findMate()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        Animal currentAnimal = getAnimal();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if (animal != null && animal.getClass() == currentAnimal.getClass()){
                Animal mate = (Animal) animal;
                if(isActive() && currentAnimal.getIsGirl() && !mate.getIsGirl() && mate.canBreed()){
                    if(!currentAnimal.getHealth() || !mate.getHealth()){
                        currentAnimal.setUnhealthy();
                        mate.setUnhealthy();
                    }
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Returns the breeding probability of the animal
     * @return breeding probability of the animal.
     */
    abstract protected double getBreedingProbability();

    /**
     * Returns the maximum number of babies the animal can give birth to at once.
     * @return max litter size of the animal.
     */
    abstract protected int getMaxLitterSize();

    /**
     * Returns the current animal occupying the location.
     * @return the current animal.
     */
    abstract protected Animal getAnimal();

    /**
     * Returns the animal's current food level.
     * @return the animal's food level.
     */
    protected double getFoodLevel(){
        return foodLevel;
    }

    /**
     * Sets the animal's food level.
     * @param food level The amount of food the animal gets.
     */
    protected void setFoodLevel(double foodlevel){
        this.foodLevel += foodlevel ; 
    }

    /**
     * Make this animal more hungry. This could result in the animal's death.
     */
    protected void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * Look for preys adjacent to the current location.
     * Only the first live prey is eaten.
     * @param probability The probability the animal finds prey.
     * @return Where food was found, or null if it wasn't.
     */
    protected Location findFood(double probability)
    {

        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        if(getRandom().nextDouble() < probability && getFoodLevel() < getMaxFoodLevel()){
            while(it.hasNext()) {
                Location where = it.next();
                Object animal = field.getObjectAt(where);
                if(animal != null && animal  instanceof Actor){
                    Actor currentAnimal = (Actor) animal;
                    for(Actor prey: getFood().keySet())
                    {
                        if(prey.getClass() == currentAnimal.getClass()){
                            if (currentAnimal instanceof Animal){
                                Animal current = (Animal)currentAnimal;
                                if(!current.getHealth()){
                                    setUnhealthy();
                                }
                            }
                            currentAnimal.setDead();
                            setFoodLevel(getFood().get(prey)  + currentAnimal.getGrowthLevel());
                            if(getFoodLevel() > getMaxFoodLevel()){
                                setFoodLevel(getMaxFoodLevel() - getFoodLevel());
                            }
                            return where;
                        }
                    }
                }
            }
        }
        return null;
    }

    /**
     * Returns the HashMap which contains what prey the animal eats and the amount of food each prey gives.
     * @return The HashMap which contains the Actor and an Integer.
     */
    abstract protected HashMap<Actor, Integer> getFood();

import java.util.List;
import java.util.Random;

/**
 * An actor is a representation of a living thing in the simulation.
 *
 * @version 2022.03.01
 */
public abstract class Actor 
{
    // The actor's field.
    private Field field;
    // The actor's position in the field.
    private Location location;
    // Whether the actor is alive or not.
    private boolean alive;
    //The actor's age
    private int age;
    //how much the actor grows. This is added to the animals food level.
    private double growthLevel;
    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();
    /**
     * Create a new actor at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Actor(Field field, Location location)
    {
        this.field = field;
        setLocation(location);
        alive = true;
    }

    /**
     * Return the actor's location.
     * @return The actors's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Place the actor at the new location in the given field.
     * @param newLocation The actor's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * Return the actors's field.
     * @return The actors's field.
     */
    protected Field getField()
    {
        return field;
    }

    /**
     * Set the field.
     * @param place. The field.
     */
    protected void setField(Field place){
        field = place;
    }

    /**
     * Check whether the actor is alive or not.
     * @return true if the actor is still alive.
     */
    protected boolean isActive()
    {
        return alive;
    }

    /**
     * Set if the actor is alive or not.
     * @param alive. If the actor is alive.
     */
    protected void setAlive(boolean alive)
    {
        this.alive = alive;
    }

    /**
     * Indicate that the actor is no longer alive.
     * It is removed from the field.
     */
    protected void setDead()
    {
        setAlive(false);
        if(getLocation() != null) {
            getField().clear(getLocation());
            location = null ;
            field = null;
        }
    }

    /**
     * Make this actor act - that is: make it do
     * whatever it wants/needs to do.
     * @param newActors A list to receive newly born actors.
     * @param simulator The simulator.
     */
    public abstract void act(List<Actor> newActors, Simulator simulator);

    /**
     * Get age of an actor
     * @return age of the actor.
     */
    protected int getAge(){
        return age;
    }

    /**
     * Set age of an actor
     * @param age. Age of the actor.
     */
    protected void setAge(int  age){
        this.age = age ;
    }

    /**
     * Increase the age. This could result in the actor's death.
     * Actor's age only increases once every 4 steps.
     * @param step. The number of steps in the simulation
     */
    protected void incrementAge(int step)
    {
        if(step % 4 == 0){
            age++;
        }
        if(age > getMaxAge()) {
            setDead();
        }
    }

    /**
     * Gets the max age of an actor.
     * @return Max age of the actor.
     */
    abstract protected int getMaxAge();

    /**
     * Return how much the actor has grown.
     * @return  How much the actor grows.
     */
    protected double getGrowthLevel(){
        return growthLevel;
    }

    /**
     * Increase the actor growth level by how much the actor has grown during this step.
     * @param value. How much more the actor has grown.
     */
    protected void setGrowthLevel(double value){
        growthLevel = value + growthLevel;
    }

    /**
     * Returns the shared random generator object
     * @return The random generator object
     */
    protected Random getRandom(){
        return rand;
    }
}

import java.util.List;
import java.util.Random;

/**
 * A class representing shared characteristics of plants.
 *
 * @version 2022.03.01
 */
public abstract class Plants extends Actor
{
    //private static final Random rand = Randomizer.getRandom();
    private int sunLevel; 
    private int waterLevel;
    /**
     * Create a new plant at location in field.
     *
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Plants(Field field, Location location)
    {
        super(field,location);
        sunLevel = getRandom().nextInt(10) + 1;
        waterLevel = getRandom().nextInt(10) + 1;
    }


    /**
     * Generate a number representing how much a plant grows,if it can grow.
     * @return The number of squares it grows into(may be zero).
     */
    protected int growth(int step)
    {
        int births = 0;
        if(getAge() >= getBreedingAge() && getAge() % 2 == 0 ) {
            births = getRandom().nextInt(getMaxLitter()) + 1;
        }

        if(step > 1600){
            births = births + 20;
        }
        return births;
    }

    /**
     * Get growing age of a plant.
     * @return Growing age of the plant.
     */
    abstract protected int getBreedingAge();

    /**
     * Get the maximum number of squares the plant can grow into.
     * @return  The number of squares the plant can grow into.
     */
    abstract protected int getMaxLitter();  

    /**
     * Increase the current water level.
     */
    protected void increaseWaterLevel(){
        waterLevel++;
    }

    /**
     * Decrease the current water level.
     */
    protected void decreaseWaterLevel(){
        waterLevel--;
    }

    /**
     * Increase the current sun level.
     */
    protected void increaseSunLevel(){
        sunLevel++;
    }

    /**
     * Decrease the current sun level.
     */
    protected void decreaseSunLevel(){
        sunLevel--;
    }

    /**
     * Get the current water level.
     * @return The plants current water level.
     */
    protected int getWaterLevel(){
        return waterLevel;
    }

    /**
     * Get the current sun level.
     * @return The plants current sun level.
     */
    protected int getSunLevel(){
        return sunLevel;
    }

    /**
     * If either the water level or the sun level is 0 the plant dies.
     * @param step. The number of steps in the simulation.
     */
    protected void incrementAge(int step){
        super.incrementAge(step);
        if(waterLevel == 0 || sunLevel == 0){
            setDead();
        }
    }
}

import java.util.List;
import java.util.Iterator;
import java.util.Random;
import java.util.HashMap;
/**
 * A simple model of a Cheetah.
 * Cheetahs age, move, eat zebras, breed and die.
 *
 * @version 2022.03.01
 */
public class Cheetah extends Predator
{
    // Characteristics shared by all Cheetahs (class variables).

    // The age at which a Cheetah can start to breed.
    private static final int BREEDING_AGE = 2;
    // The age to which a Cheetah can live.
    private static final  int MAX_AGE = 1200;
    // The likelihood of a Cheetah breeding.
    private static  double BREEDING_PROBABILITY = 0.4196975694969952;  
    // The maximum number of births.
    private static final int MAX_LITTER_SIZE = 4;
    private static final int MAX_TIME_UNTIL_BREEDING_AGAIN = 11;
    // The minimum food value of a single prey. In effect, this is the
    // number of steps a Cheetah can go before it has to eat again.
    // Cheetahs have 2 prey
    private static final int ZEBRA_FOOD_VALUE = 34; 
    private static final int GAZELLE_FOOD_VALUE = 33;
    private static final double MAX_FOOD_LEVEL = 40;

    // The likelihood of a Cheetah finding food depending on the weather.
    private static final double SUNNY_FINDING_FOOD_PROBABILITY = 0.9;
    private static final double RAINY_FINDING_FOOD_PROBABILITY = 0.8;
    private static final double FOGGY_FINDING_FOOD_PROBABILITY = 0.7;

    // Individual characteristics (instance fields).
    private HashMap<Actor, Integer> food;
    /**
     * Create a Cheetah. A Cheetah can be created as a new born (age zero
     * and not hungry) or with a random age and food level.
     * 
     * @param randomAge If true,the Cheetah will have a random age and hunger level.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Cheetah(boolean randomAge, Field field, Location location)
    {
        super(field, location);
        if(randomAge) {
            setAge(getRandom().nextInt(MAX_AGE));
            setFoodLevel(getRandom().nextInt(ZEBRA_FOOD_VALUE));
        }
        else {
            setAge(0);
            setFoodLevel(ZEBRA_FOOD_VALUE);
        }
        food = new HashMap<>();
        setGrowthLevel(getAge()/102.0);
        addFood(field);
    }

    /**
     * This is what the Cheetah does most of the time: it hunts for
     * zebras. In the process, it might breed, die of hunger,
     * die of infection or die of old age.
     * 
     * @param newCheetahs A list to return newly born Cheetahs.
     * @param simulator The simulator.
     */
    public void act(List<Actor> newCheetahs, Simulator simulator)
    {
        setGrowthLevel(0.012);
        if(simulator.isDay()){
            incrementAge(simulator.getSteps());
            incrementHunger();
            if(isActive()) {
                giveBirth(newCheetahs);  
                super.act(newCheetahs,simulator);
            }
        }else{
            //space for potential night activities
        }
    }

    /**
     * Returns the maximum number of babies the cheetah can give birth to at once.
     * @return the max litter size of the cheetah.
     */
    protected int getMaxLitterSize(){
        return MAX_LITTER_SIZE;
    }

    /**
     * Returns the breeding probability of the cheetah.
     * @return the breeding probability of the cheetah.
     */
    protected double getBreedingProbability(){
        return BREEDING_PROBABILITY;
    }

    /**
     * Returns the current cheetah occupying the location.
     * @return the current cheetah.
     */
    protected Animal getAnimal(){
        return this;
    }

    /**
     * Get breeding age of a cheetah.
     * @return The breeding age of the cheetah.
     */
    protected int getBreedingAge(){
        return BREEDING_AGE;
    }

    /**
     * Gets the max age of a cheetah.
     * @return The max age of the cheetah.
     */
    protected int getMaxAge(){
        return MAX_AGE;
    }

    /**
     * Adds the food the cheetah eats & the corresponding food value to a hashMap.
     * @param field The field the cheetah is in.
     */
    private void addFood(Field field){
        Location tempLocation = new Location(0,0);
        Zebra zebra = new Zebra(true,field,tempLocation );
        food.put(zebra, ZEBRA_FOOD_VALUE);
        zebra.setDead();
        //Location tempLocation = new Location(0,0);
        Gazelle gazelle = new Gazelle(true,field,tempLocation );
        food.put(gazelle, GAZELLE_FOOD_VALUE);
        gazelle.setDead();
    }

    /**
     * Returns the HashMap which contains what food the cheetah eats and the amount of food each prey gives.
     * @return The HashMap which contains the Actor and an Integer.
     */   
    protected HashMap<Actor, Integer> getFood(){
        return food;
    }

    /**
     * Gets the maximum food level a cheetah can have.
     * @return Max food level of the cheetah.
     */
    protected double getMaxFoodLevel(){
        return MAX_FOOD_LEVEL;
    }

    /**
     * Gets the maximum time a cheetah needs to wait until it can breed again
     * @return Max time before the cheetah can breed again.
     */
    protected int getMaxTimeUntilBreedingAgain(){
        return MAX_TIME_UNTIL_BREEDING_AGAIN;
    }

    /**
     * Gets the probability the gazelle will find food when it is sunny
     * @return The probability the gazelle will find food when it is sunny
     */
    protected double getSunnyFindingFoodProbability(){
        return SUNNY_FINDING_FOOD_PROBABILITY;
    }

    /**
     * Gets the probability the gazelle will find food when it is rainy
     * @return The probability the gazelle will find food when it is rainy
     */
    protected double getRainyFindingFoodProbability(){
        return RAINY_FINDING_FOOD_PROBABILITY;
    }

    /**
     * Gets the probability the cheetah will find food when it is foggy
     * @return The probability the cheetah will find food when it is foggy
     */
    protected double getFoggyFindingFoodProbability(){
        return FOGGY_FINDING_FOOD_PROBABILITY;
    }
}

import java.util.Random;
import java.util.List;

/**
 * A simple model of a Grass plant.
 * Grass age, breed and die.
 *
 * @version 2022.03.01
 */
public class Grass extends Plants
{
    // The age at which a grass plant can start to grow.
    private static final int BREEDING_AGE = 1;
    // The age to which a grass plant can live.
    private static final int MAX_AGE = 200;
    // The maximum number of sqaures new grass can grow into.
    private static final int MAX_LITTER_SIZE = 500;

    /**
     * Create a new grass plant at location in field.
     *
     * @param randomAge True if a random age should be generated for the grass
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Grass(boolean randomAge, Field field, Location location)
    {
        super(field, location);
        setAge(0);
        if(randomAge) {
            setAge(getRandom().nextInt(MAX_AGE));
        } 
        setGrowthLevel(getAge()/50.0);
    }

    /**
     * Make this plant act - that is: make it do
     * whatever it wants/needs to do.
     * 
     * @param newGrass A list to receive newly born grass.
     * @param simulator The simulator.
     */
    public void act(List<Actor> newGrass,Simulator simulator){
        incrementAge(simulator.getSteps());
        setGrowthLevel(0.05);
        if(simulator.isDay()){
            if(isActive()) {
                 Field field = getField();
                //sets the location to show the grass once the actor on top of it has moved.
                if (field.getObjectAt(getLocation()) == null ){
                    setLocation(getLocation());
                }else if (field.getObjectAt(getLocation()) != this && (field.getObjectAt(getLocation()) instanceof Plants)){
                    Object grassObject = field.getObjectAt(getLocation());
                    Plants grassPlant = (Plants)grassObject;
                    grassPlant.setDead();
                    setLocation(getLocation());

                }

                switch(simulator.getWeather()){
                    case SUNNY:
                        increaseSunLevel();
                        decreaseWaterLevel();
                        break;
                    case RAINY:
                        increaseWaterLevel();
                        decreaseSunLevel();
                        break;
                    case FOGGY:
                        increaseWaterLevel();
                        break;
                    default:
                        break;
                }
                List<Location> free = field.getFreeAdjacentLocations(getLocation());
                int births = growth(simulator.getSteps());
                for(int b = 0; b < births && free.size() > 0; b++) {
                    Location loc = free.remove(0);
                    Grass young = new Grass(false, field, loc);
                    newGrass.add(young);
                }
            }  
        }else{
            //space for potential night activities
        }
    }

    /**
     * Get breeding age of a grass.
     * @return int. Breeding age of the grass.
     */
    protected int getBreedingAge(){
        return BREEDING_AGE;
    }

    /**
     * Get max age of a grass.
     * @return int. Maximum age of the grass.
     */
    protected int getMaxAge(){
        return MAX_AGE;
    }

    /**
     * Get max litter size of a grass.
     * @return int. Maximum litter size of the grass;
     */
    protected int getMaxLitter(){
        return MAX_LITTER_SIZE;
    }
}

import java.util.Random;
import java.util.HashMap;
import java.util.List;

/**
 * A simple model of a Jaguar.
 * Jaguars age, move, eat gazelle, and die.
 *
 * @version 2022.03.01
 */
public class Jaguar extends Predator
{
    // Characteristics shared by all Jaguars (class variables).

    // The age at which a Jaguar can start to breed.
    private static final int BREEDING_AGE = 10;
    // The age to which a Jaguar can live.
    private static final  int MAX_AGE  = 1000;
    // The likelihood of a Jaguar breeding.
    private static final double BREEDING_PROBABILITY = 0.2; 
    // The maximum number of births.
    private static final int MAX_LITTER_SIZE = 5;
    private static final int MAX_TIME_UNTIL_BREEDING_AGAIN = 6;
    //The minimum food value of the gazelle. In effect, this is the
    // number of steps a Jaguar can go before it has to eat again.
    private static final int GAZELLE_FOOD_VALUE = 35; 
    private static final double MAX_FOOD_LEVEL = 39; 

