117	     * @return The number of births (may be zero).
118	     */
119	    protected int breed()
120	    {
121	        int births = 0;
122	        if(canBreed()  && findMate() && getRandom().nextDouble() <= getBreedingProbability() && timeLeftUntilBreedingAgain == 0) {
123	            births = getRandom().nextInt(getMaxLitterSize()) + 1;
