129	    /**
130	     * If the animal can find a mate of the opposite gender that can breed, true is returned.
131	     * @return true if the animal can find a mate.
132	     */
133	    protected boolean findMate()
134	    {
135	        Field field = getField();
136	        List<Location> adjacent = field.adjacentLocations(getLocation());
137	        Iterator<Location> it = adjacent.iterator();
138	        while(it.hasNext()) {
139	            Location where = it.next();
140	            Object animal = field.getObjectAt(where);
141	            if (animal != null && animal.getClass() == getClass()){
142	                Animal mate = (Animal) animal;
143	                if(isActive() && getIsGirl() && !mate.getIsGirl() && mate.canBreed()){
144	                    if(!getHealth() || !mate.getHealth()){
145	                        setUnhealthy();
146	                        mate.setUnhealthy();
147	                    }
148	                    return true;
149	                }
150	            }
151	        }
152	        return false;
