203	     * Look for preys adjacent to the current location.
204	     * Only the first live prey is eaten.
205	     * @param probability The probability the animal finds prey.
206	     * @return Where food was found, or null if it wasn't.
207	     */
208	    protected Location findFood(double probability)
209	    {
210	
211	        Field field = getField();
212	        List<Location> adjacent = field.adjacentLocations(getLocation());
213	        Iterator<Location> it = adjacent.iterator();
214	       
215	        if(getRandom().nextDouble() < probability && getFoodLevel() < getMaxFoodLevel()){
216	            while(it.hasNext()) {
217	                Location where = it.next();
218	                    Object animal = field.getObjectAt(where);
219	                if(animal != null && animal  instanceof Actor){
220	                    Actor currentAnimal = (Actor) animal;
221	                    Integer foodValue = getFoodValues().get(currentAnimal.getClass());
222	                    if(foodValue != null){
223	                        if (currentAnimal instanceof Animal){
224	                            Animal current = (Animal)currentAnimal;
225	                            if(!current.getHealth()){
226	                                setUnhealthy();
227	                            }
228	                        }
229	                        currentAnimal.setDead();
230	                        setFoodLevel(foodValue + currentAnimal.getGrowthLevel());
231	                        if(getFoodLevel() > getMaxFoodLevel()){
232	                            setFoodLevel(getMaxFoodLevel() - getFoodLevel());
233	                        }
234	                        return where;
235	                    }
236	                }
237	            }
238	        }
239	        return null;
240	    }
